inline int languageIndex(const char *locale) noexcept {
    if(!locale||!locale[0]||!locale[1])return 1;
    const auto lower=[](char c){return c>='A'&&c<='Z'?char(c+('a'-'A')):c;};
    const char first=lower(locale[0]),second=lower(locale[1]);
    constexpr const char *codes[]={"es","en","it","fr","de"};
    for(int i=0;i<5;++i)if(first==codes[i][0]&&second==codes[i][1]&&(locale[2]=='\0'||locale[2]=='-'||locale[2]=='_'))return i;
    return 1;
}
inline std::atomic<int> language{languageIndex(QLocale::system().bcp47Name().toUtf8().constData())};
inline void setLanguage(const char *locale) noexcept {language.store(languageIndex(locale),std::memory_order_relaxed);}
inline const char *text(const char *source) noexcept {
    if(!source)return "";
    std::size_t low=0,high=std::size(translations);
    while(low<high){const auto middle=low+(high-low)/2;const auto cmp=std::strcmp(source,translations[middle].source);
        if(cmp==0)return translations[middle].values[language.load(std::memory_order_relaxed)];
        if(cmp<0)high=middle;else low=middle+1;}
    return source;
}
inline QString string(const char *source){return QString::fromUtf8(text(source));}
